# coverage.map -- which source paths each suite reads, so a commit runs only the suites its staged
# paths can break. tests/select-suites.sh reads this file; its header has the rules in full.
#
# Line forms (a keyword or a suite file name, then globs; a word may repeat on several lines):
#   <suite file>  <glob>...   the suite READS these paths: staging one runs the suite
#   tree <suite>  <glob>...   a whole-tree check: staging a match runs it, but it claims nothing,
#                             so it can never be what makes a path count as covered
#   core          <glob>...   the shared core: staging one runs EVERY suite
#   exempt        <glob>...   shipped, and read by no suite on purpose; staging one runs no suite
#                             of its own (a tree check that matches still runs)
#   refs <suite>  <glob>...   the suite NAMES these paths without reading them (fixture text), so
#                             the literal-reference check below does not require a claim
# Globs: `*` is any run of characters but `/`, `**` any run including `/`, `?` one character but `/`.
#
# The fail-safe is "all", never "none": a staged path in the core, or one nothing claims and no
# exemption names, runs every suite. `sh tests/select-suites.sh --check` (run by
# test-select-suites.sh) refuses a tracked file nothing claims or exempts, a suite with no line
# here, a line naming no suite, a glob that matches no tracked file, and a suite that names a tracked
# path it does not claim. A suite file claims itself; it needs no line for that.

# --- the shared core: what every suite runs through -------------------------------------------
core tests/run-all.sh tests/git-isolate.sh tests/git-isolated.gitconfig tests/select-suites.sh
core dot_gitconfig
core private_dot_local/bin/executable_install-test-gate private_dot_local/bin/executable_git-staged-run
core run_onchange_install-git-hooks.sh.tmpl

# --- whole-tree checks -------------------------------------------------------------------------
tree test-shell-parse.sh        setup/** tests/*.sh private_dot_local/bin/**
tree test-python39-syntax.sh    private_dot_local/bin/**
tree test-portability-lint.sh   private_dot_local/bin/** setup/** tests/*.sh tests/coverage.map
tree test-tooling-inventory.sh  private_dot_local/bin/**
tree test-repo-hygiene.sh       **
tree test-select-suites.sh      **

